// everythingRustPtr is a slice's first element for C; nil when empty.
func everythingRustPtr[T any](s []T) *T {
	if len(s) == 0 {
		return nil
	}
	return &s[0]
}

// everythingRustBytes is a byte slice for C; nil when empty.
func everythingRustBytes(b []byte) *C.uint8_t {
	if len(b) == 0 {
		return nil
	}
	return (*C.uint8_t)(unsafe.Pointer(&b[0]))
}

// SlugifyBatch runs Slugify over many s values kept in Rust: built once, then each
// Run maps them all in one call, on all cores. Safe for concurrent Run and Rank; call
// Close when done (a finalizer frees it otherwise).
type SlugifyBatch struct {
	h unsafe.Pointer
	n int
}

// NewSlugifyBatch copies the items into Rust.
func NewSlugifyBatch(items []string) *SlugifyBatch {
	total := 0
	for _, s := range items {
		total += len(s)
	}
	bytes := make([]byte, 0, total)
	lens := make([]C.size_t, len(items))
	for i, s := range items {
		bytes = append(bytes, s...)
		lens[i] = C.size_t(len(s))
	}
	h := C.everything_rust_b_Slugify_new(everythingRustBytes(bytes), C.size_t(len(bytes)), everythingRustPtr(lens), C.size_t(len(items)))
	if h == nil {
		panic("everything-rust: building SlugifyBatch failed")
	}
	b := &SlugifyBatch{h: h, n: len(items)}
	runtime.SetFinalizer(b, (*SlugifyBatch).Close)
	return b
}

// Close frees the items on the Rust side.
func (b *SlugifyBatch) Close() {
	if b.h != nil {
		C.everything_rust_b_Slugify_free(b.h)
		b.h = nil
	}
}

// Run returns Slugify's result for every item, in order.
func (b *SlugifyBatch) Run(max int) []string {
	var errp *C.char
	var res unsafe.Pointer
	var total C.size_t
	status := C.everything_rust_b_Slugify_run(b.h, C.int64_t(max), &res, &total, &errp)
	runtime.KeepAlive(b)
	if status == 1 {
		panic(everythingRustErr(errp))
	}
	// Rust writes the results straight into Go memory; each result is a slice of it.
	buf := make([]byte, int(total))
	lens := make([]C.size_t, b.n)
	C.everything_rust_b_take_strings(res, everythingRustBytes(buf), total, everythingRustPtr(lens), C.size_t(b.n))
	all := unsafe.String(unsafe.SliceData(buf), len(buf))
	out := make([]string, b.n)
	at := 0
	for i, n := range lens {
		out[i] = string(all[at : at+int(n)])
		at += int(n)
	}
	return out
}

