// Close frees the items on the Rust side.
func (b *ParsePortBatch) Close() {
	if b.h != nil {
		C.everything_rust_b_ParsePort_free(b.h)
		b.h = nil
	}
}

// Run returns ParsePort's result for every item, in order.
func (b *ParsePortBatch) Run() ([]int, error) {
	var errp *C.char
	values := make([]C.int64_t, b.n)
	status := C.everything_rust_b_ParsePort_run(b.h, everythingRustPtr(values), C.size_t(b.n), &errp)
	runtime.KeepAlive(b)
	if status == 1 {
		return nil, errors.New(everythingRustErr(errp))
	}
	out := make([]int, b.n)
	for i, v := range values {
		out[i] = int(v)
	}
	return out, nil
}

// Rank returns the indexes of the items whose result is at least min, highest first.
func (b *ParsePortBatch) Rank(min float64) ([]int, error) {
	var errp *C.char
	order := make([]C.uint32_t, b.n)
	var n C.size_t
	status := C.everything_rust_b_ParsePort_rank(b.h, C.double(min), everythingRustPtr(order), C.size_t(b.n), &n, &errp)
	runtime.KeepAlive(b)
	if status == 1 {
		return nil, errors.New(everythingRustErr(errp))
	}
	out := make([]int, int(n))
	for i := range out {
		out[i] = int(order[i])
	}
	return out, nil
}
